source('scripts/0_helper_functions/helper_calculation_function.R')
source('scripts/0_helper_functions/helper_run_scenarios.R')
source('scripts/0_helper_functions/helper_examine_psa_results.R')
load('output/intermediate/psa_price_base.rdata')
options(scipen=999)

# ------------------------------------------------------------------------------
# Functions run calculation of outcomes (expenditure, savings) based on prices
# generated by PSA, for comparison and final compilation at the regional and
# country level
# ------------------------------------------------------------------------------
# Input: output/intermediate/psa_price_base.rdata
# ------------------------------------------------------------------------------
# Output: 
# output/intermediate/psa_outcomes_base.rdata
# output/intermediate/psa_countrylevel_base.rdata
# output/intermediate/psa_outcomes_real.rdata
# output/intermediate/psa_countrylevel_real.rdata
# ------------------------------------------------------------------------------

# Regional level, 100% vaccination coverage
full_outcome_base <- run_scenario(coverage = 'full', mode = 'psa')
save(full_outcome_base,file = 'output/intermediate/psa_outcomes_base.rdata')
# Country level, 100% vaccination coverage
country_level_psa <- get_country_level_psa_all(psa_mat = psa_mat, coverage = 'full')
save(country_level_psa,file = 'output/intermediate/psa_countrylevel_base.rdata')

# Regional level, real vaccination coverage
real_outcome_base <- run_scenario(coverage = 'real', mode = 'psa')
save(real_outcome_base,file = 'output/intermediate/psa_outcomes_real.rdata')
# Country level, real vaccination coverage
country_level_psa <- get_country_level_psa_all(psa_mat = psa_mat, coverage = 'real')
save(country_level_psa,file = 'output/intermediate/psa_countrylevel_real.rdata')
